<?php namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class CashSession extends Model { public $timestamps=false; protected $fillable=['opened_by','closed_by','opening_amount','status','notes','branch','opened_at','closed_at']; protected $casts=['opening_amount'=>'decimal:2','opened_at'=>'datetime','closed_at'=>'datetime']; public function opener(){return $this->belongsTo(User::class,'opened_by');} public function closer(){return $this->belongsTo(User::class,'closed_by');} public function orders(){return $this->hasMany(Order::class,'cash_session_id');} public function withdrawals(){return $this->hasMany(CashWithdrawal::class,'session_id');} public function closingCount(){return $this->hasOne(CashClosingCount::class,'session_id');} public function scopeOpen($q){return $q->where('status','open');}}
